Plan:
Treat F10:F14 as a membership list of criteria and sum D6:D13 for each month in F5:H5. For each month, include rows whose B date falls in that calendar month and whose C value matches any nonblank item in the list. Write the three resulting numbers into F6:H6.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def clean_key(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, (int, float)):
        f = float(value)
        if f.is_integer():
            return ("num", int(f))
        return ("num", f)
    s = str(value).strip()
    if not s:
        return None
    return ("text", s.lower())

def to_datetime(value):
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime(value.year, value.month, value.day)
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        try:
            return datetime.fromisoformat(s[:10])
        except Exception:
            return None
    return None

criteria = set()
for r in range(10, 15):
    k = clean_key(vws.cell(row=r, column=6).value)
    if k is not None:
        criteria.add(k)

def month_bounds(dt):
    start = datetime(dt.year, dt.month, 1)
    if dt.month == 12:
        end = datetime(dt.year + 1, 1, 1) - timedelta(days=1)
    else:
        end = datetime(dt.year, dt.month + 1, 1) - timedelta(days=1)
    return start, end

results = {}
for col in ("F", "G", "H"):
    month_date = to_datetime(vws[f"{col}5"].value)
    total = 0.0

    if month_date is not None:
        start, end = month_bounds(month_date)
        for r in range(6, 14):
            row_date = to_datetime(vws.cell(row=r, column=2).value)
            if row_date is None:
                continue
            if not (start <= row_date <= end):
                continue

            row_key = clean_key(vws.cell(row=r, column=3).value)
            if row_key not in criteria:
                continue

            amount = vws.cell(row=r, column=4).value
            if amount is None:
                continue
            try:
                total += float(amount)
            except (TypeError, ValueError):
                pass

    results[col] = int(total) if float(total).is_integer() else total
    ws[f"{col}6"] = results[col]

print("criteria:", criteria)
print("results:", results)

wb.save(OUT)
